import re,sys,unicodedata as u
N=lambda s:u.normalize('NFC',s)
MISSES=[]
def rep(s,a,b,label):
    if a in s: return s.replace(a,b)
    L=s.split('\n'); na=N(a); hit=0
    for k,l in enumerate(L):
        if na in N(l): L[k]=N(l).replace(na,b); hit+=1
    if not hit: print('MISS',label,a[:60]); MISSES.append(a)
    return '\n'.join(L)
p='src/i18n/translations.ts'; s=open(p,encoding='utf-8').read()
i=s.index('\n  ar: {\n'); head,ar=s[:i],s[i:]
for a,b in TR.items(): ar=rep(ar,a,b,'tr')
open(p,'w',encoding='utf-8').write(head+ar)
